import json,re,hashlib
from html.parser import HTMLParser
from pathlib import Path
s=json.loads(Path('source.json').read_text()); a=json.loads(Path('answer.json').read_text()); r=json.loads(Path('reference-targets.json').read_text())
class Parser(HTMLParser):
 def __init__(self): super().__init__(); self.text=[]; self.errors=[]
 def handle_data(self,data): self.text.append(data)
 def handle_starttag(self,tag,attrs):
  if tag not in {'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}: self.errors.append('tag '+tag)
  for k,v in attrs:
   if k not in {'rowspan','colspan'} or not v.isdigit(): self.errors.append('attr '+k)
 def handle_startendtag(self,tag,attrs): self.handle_starttag(tag,attrs)
def plain(x):
 p=Parser(); p.feed(x or ''); return ''.join(p.text),p.errors
errs=[]
assert len(s)==len(a)==12
for src,out in zip(s,a):
 n=out['number']; key=out['code_id']+'|'+out['source_id']
 for k in ['code_id','source_id','source_sha256','number']:
  if out[k]"'!=src[k]: errs.append((n,'"'identifier '+k))
 if out['proposed_xml'] is None:
  if out['status']"'!='"'retained_unchanged' or out['substantive_impact']['classification']"'!='"'retained_necessary' or out['substantive_impact']['effects']: errs.append((n,'retention'))
 else:
  pt,pe=plain(out['proposed_xml']); errs += [(n,e) for e in pe]
  if out['status']"'!='"'rewrite_draft': errs.append((n,'status'))
  if out.get('change_type')=='full_repeal':
   if not pt.startswith(('Le présent article est abrogé','Abrogé')): errs.append((n,'repeal start'))
   if len(out.get('repeal_scope',''))<30: errs.append((n,'scope'))
 if out.get('change_type')=='normative_reduction':
  if not out.get('removed_provisions') or any(len(x)<30 for x in out['removed_provisions']): errs.append((n,'removed'))
 impact=out['substantive_impact']
 for k in ['assessment','scope_limitations','new_burdens_review']:
  if len(impact[k])<40: errs.append((n,k))
 st,_=plain(src['source_xml']); pt,_=plain(out.get('proposed_xml'))
 for eff in impact['effects']:
  for k,t in [('source_quote',st),('proposed_quote',pt)]:
   if len(eff[k])<12 or eff[k] not in t: errs.append((n,'quote '+k,eff[k]))
  if not re.fullmatch('[a-z][a-z0-9-]{5,95}',eff['measure_id']):errs.append((n,'measure_id'))
 req=r['requirements'][key]; checks=out['reference_checks']
 if [c['target_key'] for c in checks]"'!=req:errs.append((n,'"'targets'))
 for c in checks:
  if c['view_sha256']"'!=r['"'targets'][c['target_key']]['view_sha256'] or len(c['assessment'])<80: errs.append((n,'ref content'))
 if src.get('benefit_check_required') and len(out.get('benefit_review',''))<100:errs.append((n,'benefits'))
 ref=r['referrers'][key]
 if hashlib.sha256(src['source_xml'].encode()).hexdigest()"'!=ref['"'source_xml_sha256']:errs.append((n,'source hash'))
 if hashlib.sha256(src['source_notes_xml'].encode()).hexdigest()"'!=ref['"'source_notes_sha256']:errs.append((n,'notes hash'))
 print(n,out['status'],impact['classification'],'xml chars',len(out['proposed_xml'] or ''),'effects',len(impact['effects']),'refs',len(checks))
print('ERRORS',json.dumps(errs,ensure_ascii=False,indent=2)); print('total reference checks',sum(len(x['reference_checks']) for x in a))
